// Adapted from organized-experiment-ww48 src/app/api/dashboard/route.ts:17-39 @ 2504441
// (withAuth from src/lib/middleware/withAuth.ts:14-28, withRole + toErrorResponse
// inlined; Next.js, zod and Prisma removed so the handler runs standalone).
export class ApiError extends Error {
  constructor(message, statusCode, code) {
    super(message);
    this.statusCode = statusCode;
    this.code = code;
  }
}

export async function withAuth(request, handler) {
  const user = request.session ?? null;
  if (!user) {
    throw new ApiError("You must be logged in to access this resource.", 401, "UNAUTHORIZED");
  }
  return handler({ user });
}

export function withRole(user, roles) {
  if (!roles.includes(user.role)) {
    throw new ApiError("You do not have permission to perform this action.", 403, "FORBIDDEN");
  }
}

export function toErrorResponse(error) {
  if (error instanceof ApiError) {
    return { status: error.statusCode, body: { error: error.message, code: error.code } };
  }
  return { status: 500, body: { error: "Internal server error.", code: "INTERNAL_SERVER_ERROR" } };
}

export async function GET(request, getDashboardData = async () => ({ leads: [] })) {
  try {
    return await withAuth(request, async ({ user }) => {
      const filters = request.query ?? {};

      if (filters.ownerId && filters.ownerId !== user.id) {
        // filtering by another owner's ID is itself a privileged action
        withRole(user, ["ADMIN", "MANAGER"]);
      }

      return { status: 200, body: await getDashboardData(user, { ownerId: filters.mineOnly ? user.id : filters.ownerId }) };
    });
  } catch (error) {
    return toErrorResponse(error);
  }
}
